from pathlib import Path
import subprocess,sys
r=Path.cwd();profile=sys.argv[1];platform=sys.argv[2]if len(sys.argv)>2 else'windows'
if platform=='windows':
 command=['cargo','build','--locked','-p','deadlib-lua','--target-dir','target/lua-native-hooks','--example','library_initializers']+(['--release']if profile=='current'else[])
 assert subprocess.call(command)==0
for name in ['io-init','openlibs','io-input','io-loadstdin']:
 command=([sys.executable,str(r/('target/lua-native-hooks/compare-'+name+('-i686'if platform=='i686'else'')+'.py')),profile])
 result=subprocess.call(command)
 if result:raise SystemExit(result)
